createDataURL = function() {
    const input = document.createElement('input');
    input.type = 'file';
	input.onchange = _ => {
        const files = Array.from(input.files);
        const reader = new FileReader();
        reader.onload = function(){ 
		    var binary = '';
			var bytes = new Uint8Array( reader.result );
			var len = bytes.byteLength;
			for (var i = 0; i < len; i++) {
				binary += String.fromCharCode( bytes[ i ] );
			}
		    filetype = "application/octet-stream"
            result = "data:"+filetype+";base64,"+btoa(binary);
			output = document.getElementById('dataurl');
			output.innerHTML = result;
			output.outerHTML = output.outerHTML+" ";
			output.addEventListener("click", function() {
        this.style.height = "auto";
        this.style.height = Math.max(this.scrollHeight, 16) + "px";
    });
        };
        reader.readAsArrayBuffer(input.files[0]);
    }
    input.click();
// sinput.remove();    
  };

echo('<button onclick="createDataURL()">Open</button><div class="cell edit><textarea class="cellsource" id="dataurl"></textarea><div>')
